271	  padding: 40px;          /* Breathing room around chart */
272	  min-height: 360px;      /* Substantial presence on dashboard */
273	  background: var(--surface);
274	  border-radius: 12px;
275	  border: 1px solid var(--border);
276	}
277	
278	/* Remove excessive grid lines */
279	.chart-canvas {
280	  border-radius: 8px;     /* Inner chart gets smaller radius */
281	}
