          <div class="legend-item"><span class="legend-dot" style="background:#8b5cf6"></span>Processing</div>
          <div class="legend-item"><span class="legend-dot" style="background:#f59e0b"></span>Retail</div>
          <div class="legend-item"><span class="legend-dot" style="background:#f43f5e"></span>Consumption</div>
