              <div class="priority-metric"><span class="text-secondary">Carbon Share</span><span class="value">31%</span></div>
              <div class="priority-metric"><span class="text-secondary">Avoidable</span><span class="value">52%</span></div>
              <div class="priority-metric"><span class="text-secondary">Saveable</span><span class="value">280 Mt</span></div>
